using System;using System.IO;using System.Text;using System.Collections;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckMusicalParking {
public sealed class ParkingProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsParking")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.ParkingProbe",false);UnityEditor.SessionState.SetBool("LWS.ParkingProbe",false);
#endif
 if(run){var g=new GameObject("Musical Parking autonomous match acceptance");DontDestroyOnLoad(g);if(FindAnyObjectByType<SportsProbeInputIsolation>()==null)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<ParkingProbe>();}}
 ParkingMatch m;bool had,restored;string saved,folder;int errors;readonly StringBuilder log=new StringBuilder();void Check(bool ok,string label){log.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;Write();}void Write(){File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+s);Write();}}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("ParkingEvidence");yield return SportsProbeScene.Ensure<ParkingMatch>("TruckMusicalParking");m=FindAnyObjectByType<ParkingMatch>();yield return null;had=LWS.TruckSports.SportsPrefs.HasKey(m.PreferenceKey);saved=LWS.TruckSports.SportsPrefs.GetString(m.PreferenceKey);Application.logMessageReceived+=Error;for(int difficulty=0;difficulty<3;difficulty++){m.SetupScreen();m.AllBots();for(int i=0;i<8;i++)m.setup.players[i].difficulty=(BowlingDifficulty)difficulty;Check(m.StartMatch(),"eight-AI full parking match starts difficulty="+difficulty);Time.timeScale=4;while(m.Phase==ParkingPhase.Countdown)yield return null;Check(m.Phase==ParkingPhase.Music&&m.music.isPlaying,"music phase and looping track start");yield return new WaitForSeconds(.4f);m.Pause();float age=m.Age;int sample=m.music.timeSamples;var p=m.trucks[0].body.position;yield return new WaitForSecondsRealtime(.15f);Check(m.Age==age&&p==m.trucks[0].body.position&&m.music.timeSamples==sample,"pause preserves actual circulation and music sample position");m.Resume();Time.timeScale=4;float end=Time.realtimeSinceStartup+600,next=0;int round=0;while(!m.Finished&&Time.realtimeSinceStartup<end){if(m.Round!=round){round=m.Round;log.AppendLine("ROUND "+round+" remaining="+m.Remaining);}if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",log+"LIVE level="+difficulty+" round="+m.Round+" phase="+m.Phase+" age="+m.Age+" captures="+m.TotalCaptures+" owners="+string.Join(",",m.secured)+" errors="+errors);next=Time.realtimeSinceStartup+2;}yield return null;}Check(m.Finished&&m.Winner>=0&&m.Round==7&&m.Remaining==1,"exact seven eliminations produce one winner difficulty="+difficulty);Check(m.TotalCaptures>=14,"actual stable physical parking captures across match difficulty="+difficulty+" captures="+m.TotalCaptures);log.AppendLine("MATCH difficulty="+difficulty+" winner="+m.Winner+" captures="+m.TotalCaptures+" seed="+m.Seed);Time.timeScale=1;}
 log.AppendLine("ERRORS="+errors+". Actual NWH/PhysX, autonomous AI matches and native music/pause observation; no hardware/human or subjective audio validation.");File.WriteAllText(folder+"/result.txt",log.ToString());Debug.Log("PARKING_PROBE_COMPLETE "+log);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null){m.SetupScreen();if(had)LWS.TruckSports.SportsPrefs.SetString(m.PreferenceKey,saved);else LWS.TruckSports.SportsPrefs.DeleteKey(m.PreferenceKey);LWS.TruckSports.SportsPrefs.Save();}Time.timeScale=1;}void OnDestroy(){Restore();}
#endif
}
}
